package com.hbm.machine.oreslopper;
import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class OreSlopperContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");
 public static final DeferredBlock<OreSlopperBlock> BLOCK=BLOCKS.register("machine_ore_slopper",OreSlopperBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem(BLOCK);
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<OreSlopperBlockEntity>> ENTITY=ENTITIES.register("ore_slopper",()->BlockEntityType.Builder.of(OreSlopperBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<OreSlopperPort>> PORT=ENTITIES.register("ore_slopper_port",()->BlockEntityType.Builder.of(OreSlopperPort::new,BLOCK.get()).build(null));
 public static final DeferredHolder<MenuType<?>,MenuType<OreSlopperMenu>> MENU=MENUS.register("ore_slopper",()->new MenuType<>((IContainerFactory<OreSlopperMenu>)OreSlopperMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static ResourceLocation id(String name){return ResourceLocation.fromNamespaceAndPath("hbm",name);}
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);bus.addListener(OreSlopperContent::capabilities);}
 private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,PORT.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));}
 public static List<ItemStack> creativeStacks(String tab){return tab.equals("machine")?List.of(new ItemStack(ITEM.get())):List.of();}
 private OreSlopperContent(){}
}